# Prompts do processo validado em testes_modelos_ia (prompts_regras.py), sem alterações de conteúdo.
# PROMPT_ALINHAMENTO é a única adição: só posiciona cada pictograma sobre a palavra da frase original
# e não influencia simplificação, extração, busca nem escolha de pictogramas.


PROMPT_SIMPLIFICACAO = 'Você é um sistema de apoio à Comunicação Aumentativa e Alternativa (CAA). Reescreva a frase em português seguindo as diretrizes da Leitura Fácil, para que ela possa ser representada por pictogramas concretos:\n1. Ordem direta (sujeito, verbo, complemento) e voz ativa. Evite orações subordinadas longas.\n2. Use palavras concretas e de uso comum. Use sempre a mesma palavra para a mesma coisa.\n3. Substitua metáforas, expressões idiomáticas e figuras de linguagem pelo SENTIDO LITERAL. Não apague o conteúdo: traduza-o. Exemplo: \'chutar a questão na prova\' -> \'responder sem saber a resposta\'.\n4. Não invente fatos, não dê opinião e não mude o sentido original. Mantenha datas e números essenciais.\n5. Se a frase já for simples, devolva-a quase igual.\nResponda APENAS com um JSON no formato exato: {"frase_simplificada": "..."}. Não inclua texto antes ou depois do JSON.'

PROMPT_EXTRACAO = 'Você é um sistema de apoio à Comunicação Aumentativa e Alternativa (CAA). Dada uma frase em português, extraia APENAS as palavras-chave que carregam significado comunicativo concreto (as ideias centrais que uma pessoa precisaria expressar), seguindo RIGOROSAMENTE estas regras:\n1. Separe a frase em palavras-chave (conceitos), não frases inteiras.\n2. REMOVA todas as palavras funcionais, incluindo: artigos (o, a, os, as, um, uma), preposições (de, em, por, para, com, até, sobre, entre), conjunções (e, mas, que, se, pois, porque), pronomes (ele, ela, lhe, se, nos, seu, sua) e verbos auxiliares usados apenas como ligação (é, são, está, foi, há) QUANDO não forem o foco semântico da frase.\n3. Retire sinais de pontuação (!, ?, ., ,, ;, : etc.).\n4. Retire espaços extras e qualquer caractere especial.\n5. Coloque verbos no infinitivo (ex.: \'comendo\' -> \'comer\') e substantivos no singular (ex.: \'maçãs\' -> \'maçã\').\n6. NÃO troque palavras por outras mais gerais ou diferentes; apenas normalize as palavras que já estão na frase.\nResponda APENAS com um JSON no formato exato: {"palavras_chave": ["PALAVRA1", "PALAVRA2", ...]}. Não inclua texto antes ou depois do JSON.'

SISTEMA_SINONIMO = 'Você é um assistente de busca de sinônimos para um sistema de CAA.'
PROMPT_SINONIMO = 'Na frase: "{frase}"\nA palavra "{palavra}" não tem pictograma correspondente em um repositório visual voltado para comunicação cotidiana e concreta. Sugira UM único sinônimo em português MAIS CONCRETO e MAIS PRÓXIMO possível do sentido original nesse contexto — evite trocar por uma palavra genérica demais (por exemplo, não troque \'criatura\' por \'ser\', prefira algo como \'monstro\' ou \'animal\' se for mais fiel ao contexto). Normalize também (verbo no infinitivo ou substantivo no singular, sem artigos ou pontuação). Responda APENAS com um JSON no formato exato: {{"sinonimo": "PALAVRA"}}.'

SISTEMA_ESCOLHA = 'Você é um assistente de desambiguação de sentidos para um sistema de CAA.'
PROMPT_ESCOLHA = 'Na frase: "{frase}"\nA palavra "{palavra}" não tem pictograma, mas estes termos relacionados (do dicionário WordNet) têm:\n{lista}\nEscolha o termo que MELHOR preserva o sentido de "{palavra}" NESTA frase. Se nenhum preservar o sentido (por exemplo, se todos forem de outro significado da palavra), responda 0. Responda APENAS com um JSON no formato exato: {{"escolha": NUMERO}}.'

STOPWORDS_SEGURANCA = {'a', 'o', 'as', 'os', 'um', 'uma', 'uns', 'umas', 'de', 'do', 'da', 'dos', 'das', 'em', 'no', 'na', 'nos', 'nas', 'por', 'para', 'com', 'sem', 'sobre', 'entre', 'até', 'após', 'e', 'ou', 'mas', 'que', 'se', 'quando', 'como', 'porque', 'pois', 'eu', 'tu', 'ele', 'ela', 'nós', 'vós', 'eles', 'elas', 'você', 'vocês', 'me', 'te', 'lhe', 'lhes', 'seu', 'sua', 'seus', 'suas', 'meu', 'minha', 'meus', 'minhas', 'este', 'esta', 'isto', 'esse', 'essa', 'isso', 'aquele', 'aquela', 'aquilo', 'é', 'são', 'foi', 'foram', 'só', 'já', 'não', 'sim', 'também', 'ainda', 'apenas'}

SISTEMA_ALINHAMENTO = 'Você posiciona pictogramas sobre as palavras de uma frase em português para um sistema de CAA.'
PROMPT_ALINHAMENTO = 'Você recebe a frase original dividida em palavras numeradas (começando em 0), a versão simplificada dela e uma lista de palavras-chave extraídas da versão simplificada. Para CADA palavra-chave, indique o número da palavra da frase original que ela representa (a mesma palavra flexionada ou a palavra que originou a ideia). Use -1 quando nenhuma palavra da frase original corresponder com clareza. Não invente números fora da lista. Responda APENAS com um JSON no formato exato: {"indices": [N1, N2, ...]}, com exatamente um número por palavra-chave, na mesma ordem.'
